import{_ as e,o as a,c as i,a as o}from"./chunks/framework.DB-sBtQe.js";const m=JSON.parse('{"title":"Computation","description":"","frontmatter":{},"headers":[],"relativePath":"docs/computation/index.md","filePath":"docs/computation/index.md"}'),n={name:"docs/computation/index.md"};function s(d,t,r,l,c,p){return a(),i("div",null,[...t[0]||(t[0]=[o(`<h1 id="computation" tabindex="-1">Computation <a class="header-anchor" href="#computation" aria-label="Permalink to &quot;Computation&quot;">​</a></h1><p>This chapter describes the mathematical and algorithmic foundations of MuJoCo. The overall framework is fairly standard for readers familiar with modeling and simulation in generalized or joint coordinates.</p><h2 id="soft-contact-model" tabindex="-1">Soft Contact Model <a class="header-anchor" href="#soft-contact-model" aria-label="Permalink to &quot;Soft Contact Model&quot;">​</a></h2><p>Robots as well as humans interact with their environment primarily through physical contact. The contact model underlying MuJoCo has benefits along these dimensions:</p><h3 id="physical-realism-and-soft-contacts" tabindex="-1">Physical Realism and Soft Contacts <a class="header-anchor" href="#physical-realism-and-soft-contacts" aria-label="Permalink to &quot;Physical Realism and Soft Contacts&quot;">​</a></h3><p>MuJoCo drops the strict complementarity constraint at the heart of the LCP formulation. For frictionless contacts this makes no difference, but for frictional contacts there are differences. The immediate consequence of dropping strict complementarity and replacing it with a cost is that complementarity can be violated — meaning that force and velocity in the contact normal direction can be simultaneously positive.</p><h3 id="computational-efficiency" tabindex="-1">Computational Efficiency <a class="header-anchor" href="#computational-efficiency" aria-label="Permalink to &quot;Computational Efficiency&quot;">​</a></h3><p>LCP models with frictional contact correspond to NP-hard optimization problems. To be fair, NP-hardness is a statement about worst-case performance. Convex optimization has well-established advantages. In MuJoCo, for typical robotic models, 10 sweeps of a projected Gauss-Seidel method yield solutions which for practical purposes are indistinguishable from the global minimum.</p><h3 id="continuous-time" tabindex="-1">Continuous Time <a class="header-anchor" href="#continuous-time" aria-label="Permalink to &quot;Continuous Time&quot;">​</a></h3><p>The present model is defined in <strong>continuous-time</strong>, in terms of forces and accelerations. This is more natural given that time in the real world is continuous. It is also the preferred formulation in the controls literature.</p><h3 id="inverse-dynamics-and-optimization" tabindex="-1">Inverse Dynamics and Optimization <a class="header-anchor" href="#inverse-dynamics-and-optimization" aria-label="Permalink to &quot;Inverse Dynamics and Optimization&quot;">​</a></h3><p>The contact model has a <strong>uniquely-defined inverse</strong>. The inverse dynamics are in fact easier to compute than the forward dynamics, because the optimization problem becomes diagonal and decomposes into independent optimization problems over individual contacts — which can be solved analytically.</p><h2 id="general-framework" tabindex="-1">General Framework <a class="header-anchor" href="#general-framework" aria-label="Permalink to &quot;General Framework&quot;">​</a></h2><h3 id="notation" tabindex="-1">Notation <a class="header-anchor" href="#notation" aria-label="Permalink to &quot;Notation&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Symbol</th><th>Size</th><th>Description</th><th>MuJoCo field</th></tr></thead><tbody><tr><td><code>nq</code></td><td></td><td>number of position coordinates</td><td><code>mjModel.nq</code></td></tr><tr><td><code>nv</code></td><td></td><td>number of degrees of freedom</td><td><code>mjModel.nv</code></td></tr><tr><td><code>nc</code></td><td></td><td>number of active constraints</td><td><code>mjData.nefc</code></td></tr><tr><td><code>q</code></td><td><code>nq</code></td><td>joint position</td><td><code>mjData.qpos</code></td></tr><tr><td><code>v</code></td><td><code>nv</code></td><td>joint velocity</td><td><code>mjData.qvel</code></td></tr><tr><td><code>τ</code></td><td><code>nv</code></td><td>applied force</td><td><code>qfrc_passive + qfrc_actuator + qfrc_applied</code></td></tr><tr><td><code>c(q,v)</code></td><td><code>nv</code></td><td>bias force</td><td><code>mjData.qfrc_bias</code></td></tr><tr><td><code>M(q)</code></td><td><code>nv×nv</code></td><td>inertia in joint space</td><td><code>mjData.qM</code></td></tr><tr><td><code>J(q)</code></td><td><code>nc×nv</code></td><td>constraint Jacobian</td><td><code>mjData.efc_J</code></td></tr><tr><td><code>r(q)</code></td><td><code>nc</code></td><td>constraint residual</td><td><code>mjData.efc_pos</code></td></tr><tr><td><code>f(q,v,τ)</code></td><td><code>nc</code></td><td>constraint force</td><td><code>mjData.efc_force</code></td></tr></tbody></table><h3 id="equations-of-motion" tabindex="-1">Equations of Motion <a class="header-anchor" href="#equations-of-motion" aria-label="Permalink to &quot;Equations of Motion&quot;">​</a></h3><p>The general equations of motion in continuous time are:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span>M q̈ + c = τ + Jᵀf</span></span></code></pre></div><p>Where:</p><ul><li><strong>M</strong> is the joint-space inertia matrix (always invertible)</li><li><strong>c</strong> is the bias force (Coriolis, centrifugal, gravitational)</li><li><strong>τ</strong> is the applied force</li><li><strong>Jᵀf</strong> is the constraint force in joint coordinates</li></ul><h3 id="recursive-algorithms" tabindex="-1">Recursive Algorithms <a class="header-anchor" href="#recursive-algorithms" aria-label="Permalink to &quot;Recursive Algorithms&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Algorithm</th><th>Purpose</th><th>Computational Cost</th></tr></thead><tbody><tr><td><strong>RNE</strong> (Recursive Newton-Euler)</td><td>Compute bias force <code>c</code></td><td>O(n)</td></tr><tr><td><strong>CRB</strong> (Composite Rigid-Body)</td><td>Compute inertia matrix <code>M</code></td><td>O(n)</td></tr><tr><td><strong>LDLᵀ factorization</strong></td><td>Solve <code>Mx = b</code> efficiently</td><td>O(n)</td></tr></tbody></table><h2 id="numerical-integration" tabindex="-1">Numerical Integration <a class="header-anchor" href="#numerical-integration" aria-label="Permalink to &quot;Numerical Integration&quot;">​</a></h2><p>MuJoCo supports four integrators:</p><table tabindex="0"><thead><tr><th>Integrator</th><th>Description</th><th>Recommended Use</th></tr></thead><tbody><tr><td><strong>Euler</strong></td><td>Semi-implicit with implicit joint damping</td><td>Compatibility with older models</td></tr><tr><td><strong>implicitfast</strong></td><td>Fast implicit-in-velocity</td><td><strong>Default recommendation</strong> — best tradeoff of stability and performance</td></tr><tr><td><strong>implicit</strong></td><td>Full implicit-in-velocity</td><td>Coupled rotational systems (multi-link pendula)</td></tr><tr><td><strong>RK4</strong></td><td>4th-order Runge-Kutta</td><td>Energy-conserving systems</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Choosing Integrator</p><p>The recommended integrator is <code>implicitfast</code> which usually has the best tradeoff of stability and performance. For energy-conserving systems, <code>RK4</code> is qualitatively better.</p></div><h2 id="constraint-model" tabindex="-1">Constraint Model <a class="header-anchor" href="#constraint-model" aria-label="Permalink to &quot;Constraint Model&quot;">​</a></h2><p>MuJoCo has a very flexible constraint model. Each conceptual constraint contributes one or more scalar constraints towards the total count <code>nc</code>.</p><h3 id="constraint-types-in-order" tabindex="-1">Constraint Types (in order) <a class="header-anchor" href="#constraint-types-in-order" aria-label="Permalink to &quot;Constraint Types (in order)&quot;">​</a></h3><ol><li><strong>Equality constraints</strong> — loop joints, mechanical coupling</li><li><strong>Friction loss</strong> — Coulomb friction in DOFs and tendons</li><li><strong>Limit constraints</strong> — joint and tendon limits</li><li><strong>Contact constraints</strong> — frictional contacts</li></ol><h3 id="equality-constraints" tabindex="-1">Equality Constraints <a class="header-anchor" href="#equality-constraints" aria-label="Permalink to &quot;Equality Constraints&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Dimension</th><th>Description</th></tr></thead><tbody><tr><td><code>connect</code></td><td>3</td><td>Create ball joint between two bodies</td></tr><tr><td><code>weld</code></td><td>6</td><td>Fix relative pose of two bodies</td></tr><tr><td><code>joint</code></td><td>1</td><td>Fix position of a joint</td></tr><tr><td><code>tendon</code></td><td>1</td><td>Fix length of a tendon</td></tr><tr><td><code>slide</code></td><td>1 or 2</td><td>Couple joint/tendon positions via polynomial</td></tr></tbody></table><h3 id="solver-algorithms" tabindex="-1">Solver Algorithms <a class="header-anchor" href="#solver-algorithms" aria-label="Permalink to &quot;Solver Algorithms&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Solver</th><th>Description</th></tr></thead><tbody><tr><td><strong>Newton</strong></td><td>Quadratic convergence; default for most models</td></tr><tr><td><strong>CG</strong> (Conjugate Gradient)</td><td>Good for TPU; lower memory</td></tr><tr><td><strong>PGS</strong> (Projected Gauss-Seidel)</td><td>Fast for large-scale; limited accuracy</td></tr></tbody></table><h2 id="actuation-model" tabindex="-1">Actuation Model <a class="header-anchor" href="#actuation-model" aria-label="Permalink to &quot;Actuation Model&quot;">​</a></h2><p>MuJoCo provides a flexible actuator model with three independent components:</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">graph TD</span></span>
<span class="line"><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">    A[Control Input u] --&gt; B[Transmission]</span></span>
<span class="line"><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">    B --&gt; C[Force Output p]</span></span>
<span class="line"><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">    C --&gt; D[Moment Arms ∇l]</span></span>
<span class="line"><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">    D --&gt; E[Generalized Force τ]</span></span>
<span class="line"><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">    </span></span>
<span class="line"><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">    F[Activation State w] --&gt; B</span></span>
<span class="line"><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">    B --&gt;|Transmission Types| G[joint / tendon / site / body / slider-crank]</span></span>
<span class="line"><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">    </span></span>
<span class="line"><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">    style A fill:#e3f2fd</span></span>
<span class="line"><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">    style E fill:#c8e6c9</span></span></code></pre></div><h3 id="transmission-types" tabindex="-1">Transmission Types <a class="header-anchor" href="#transmission-types" aria-label="Permalink to &quot;Transmission Types&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>joint</code></td><td>Force/torque on a joint</td></tr><tr><td><code>tendon</code></td><td>Force on a tendon</td></tr><tr><td><code>site</code></td><td>Cartesian force/torque at a site</td></tr><tr><td><code>body</code></td><td>Forces at contact points on a body</td></tr><tr><td><code>slider-crank</code></td><td>Linear-to-torque conversion</td></tr><tr><td><code>jointinparent</code></td><td>Rotation measured in parent frame (ball/free joints)</td></tr></tbody></table><h3 id="activation-dynamics" tabindex="-1">Activation Dynamics <a class="header-anchor" href="#activation-dynamics" aria-label="Permalink to &quot;Activation Dynamics&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Dynamics Equation</th></tr></thead><tbody><tr><td><code>none</code></td><td>No activation state</td></tr><tr><td><code>integrator</code></td><td>ẇᵢ = uᵢ</td></tr><tr><td><code>filter</code></td><td>ẇᵢ = (uᵢ - wᵢ) / τ</td></tr><tr><td><code>filterexact</code></td><td>ẇᵢ = (uᵢ - wᵢ)(1 - e^(-h/τ))</td></tr><tr><td><code>muscle</code></td><td>Hill-type muscle model</td></tr><tr><td><code>user</code></td><td>User-defined callback</td></tr></tbody></table><h2 id="passive-forces" tabindex="-1">Passive Forces <a class="header-anchor" href="#passive-forces" aria-label="Permalink to &quot;Passive Forces&quot;">​</a></h2><p>Passive forces depend only on position and velocity:</p><table tabindex="0"><thead><tr><th>Source</th><th>Description</th></tr></thead><tbody><tr><td><strong>Spring-dampers</strong></td><td>Joint and tendon compliance</td></tr><tr><td><strong>Gravity compensation</strong></td><td><code>gravcomp</code> attribute on bodies</td></tr><tr><td><strong>Fluid forces</strong></td><td>Viscous drag, inertia, lift</td></tr></tbody></table><h2 id="simulation-pipeline" tabindex="-1">Simulation Pipeline <a class="header-anchor" href="#simulation-pipeline" aria-label="Permalink to &quot;Simulation Pipeline&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">sequenceDiagram</span></span>
<span class="line"><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">    participant User as User Code</span></span>
<span class="line"><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">    participant Pipeline as Simulation Pipeline</span></span>
<span class="line"><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">    participant Solver as Constraint Solver</span></span>
<span class="line"><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">    participant Integ as Integrator</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">    User-&gt;&gt;Pipeline: mj_step(m, d)</span></span>
<span class="line"><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">    Pipeline-&gt;&gt;Pipeline: Forward kinematics</span></span>
<span class="line"><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">    Pipeline-&gt;&gt;Pipeline: Compute bias force c (RNE)</span></span>
<span class="line"><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">    Pipeline-&gt;&gt;Pipeline: Compute inertia M (CRB)</span></span>
<span class="line"><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">    Pipeline-&gt;&gt;Pipeline: Compute applied force τ</span></span>
<span class="line"><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">    Pipeline-&gt;&gt;Solver: Solve for constraint force f</span></span>
<span class="line"><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">    Solver--&gt;&gt;Pipeline: Return f</span></span>
<span class="line"><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">    Pipeline-&gt;&gt;Pipeline: Compute acceleration q̈</span></span>
<span class="line"><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">    Pipeline-&gt;&gt;Integ: Integrate state</span></span>
<span class="line"><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">    Integ--&gt;&gt;Pipeline: Update q, v, w</span></span>
<span class="line"><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">    Pipeline--&gt;&gt;User: Simulation step complete</span></span></code></pre></div>`,46)])])}const u=e(n,[["render",s]]);export{m as __pageData,u as default};
